import {patients as initialPatients,generateSession,publicReadings} from './lib/data.js';
import {estimate,forecast,handover,workload,validatePatient,validateReadings,MODEL_VERSION} from './lib/twin.js';
const icons={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',pulse:'M2 12h4l3-8 5 16 3-8h5',flask:'M9 3h6M10 3v7L4 20h16l-6-10V3M8 15h8',chart:'M4 3v17h17M8 15l4-5 4 2 5-7',file:'M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.8M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',alert:'M12 3 2 21h20L12 3zM12 9v5M12 18h.01',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',search:'M21 21l-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',play:'m8 4 12 8-12 8V4',pause:'M8 4v16M16 4v16',check:'m5 12 4 4L20 5',database:'M20 6c0 2-16 2-16 0s16-2 16 0v12c0 3-16 3-16 0V6M4 12c0 3 16 3 16 0',shield:'m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6l9-4',settings:'M4 6h16M4 12h16M4 18h16M8 3v6M16 9v6M10 15v6'};
const icon=k=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[k]||icons.pulse}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={'current-low':'Low pressure now',review:'Review soon',watch:'Watch',stable:'Stable',unavailable:'Data check'};
let patients=[...initialPatients],streams=Object.fromEntries(patients.map(p=>[p.id,publicReadings(generateSession(p))]));
let selected=patients[0].id,now=120,view='unit',playing=false,timer=null,speed=2,query='',quality=false,scenarioUF=.62;
let assumptions={patients:24,checks:8,manual:90,review:9},events=[],evaluation=null;
try{const stored=JSON.parse(localStorage.getItem('nephra-reviews-v1')||'[]');events=Array.isArray(stored)?stored.filter(x=>x&&typeof x.patient==='string'&&typeof x.action==='string'&&typeof x.time==='string'&&Number.isFinite(x.minute)).slice(-100):[];}catch{}
const current=()=>patients.find(p=>p.id===selected);
const effective=p=>streams[p.id].map(x=>quality&&x.minute>now-15&&x.minute<=now?{...x,quality:'poor'}:x);
function stateOf(p=current()) {const s=estimate(p,effective(p),now);return {s,f:forecast(p,s)};}
function pill(f){return `<span class="pill ${f.status}">${labels[f.status]}</span>`;}
function saveEvent(action){events.push({patient:selected,minute:now,time:new Date().toISOString(),action});events=events.slice(-100);try{localStorage.setItem('nephra-reviews-v1',JSON.stringify(events));}catch{toast('Review kept for this session; browser storage unavailable.');}}
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('visible'),4000);}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function chart(p,s,f,alternative=null){
 if(!s.valid)return `<div class="error-box">${icon('shield')} <strong>Forecast withheld</strong><br>${esc(s.reason)}</div>`;
 const W=820,H=245,left=43,right=20,top=25,bottom=34,minT=Math.max(0,now-60),maxT=now+30;
 const observed=s.observed.filter(x=>x.minute>=minT&&x.sbp!==null&&x.quality==='good');
 const values=[...observed.map(x=>x.sbp),...f.points.flatMap(x=>[x.low,x.high]),...(alternative?.points??[]).flatMap(x=>[x.low,x.high])];
 const minY=Math.floor(Math.min(80,...values)/10)*10,maxY=Math.ceil(Math.max(140,...values)/10)*10;
 const x=v=>left+(v-minT)/(maxT-minT)*(W-left-right),y=v=>top+(maxY-v)/(maxY-minY)*(H-top-bottom);
 const path=points=>points.map((v,i)=>`${i?'L':'M'}${x(v.minute).toFixed(1)},${y(v.sbp).toFixed(1)}`).join(' ');
 const band=f.points.map(v=>`${x(v.minute)},${y(v.high)}`).concat([...f.points].reverse().map(v=>`${x(v.minute)},${y(v.low)}`)).join(' ');
 let grid='';for(let a=minY;a<=maxY;a+=20)grid+=`<line x1="${left}" y1="${y(a)}" x2="${W-right}" y2="${y(a)}" stroke="#e7eeeb"/><text x="${left-10}" y="${y(a)+4}" text-anchor="end" fill="#7f928e" font-size="11">${a}</text>`;
 for(let t=minT;t<=maxT;t+=15)grid+=`<text x="${x(t)}" y="${H-10}" text-anchor="middle" fill="#7f928e" font-size="11">${t} min</text>`;
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="Systolic blood pressure: observed history and 30-minute simulated forecast. Current estimate ${s.sbp.toFixed(0)}, predicted nadir ${f.nadir.toFixed(0)} millimetres of mercury.">
 <rect x="${x(now)}" y="${top}" width="${x(maxT)-x(now)}" height="${H-top-bottom}" fill="#f5faf7"/>${grid}
 <line x1="${left}" y1="${y(90)}" x2="${W-right}" y2="${y(90)}" stroke="#d4a777" stroke-dasharray="5 5"/><text x="${left+7}" y="${y(90)-7}" fill="#ae7544" font-size="11">90 mmHg reference</text>
 <polygon points="${band}" fill="#cae8dc" opacity=".6"/><path d="${path(observed)}" fill="none" stroke="#19877d" stroke-width="2.5"/><path d="${path(f.points)}" fill="none" stroke="#19877d" stroke-width="2.5" stroke-dasharray="6 5"/>
 ${alternative?`<path d="${path(alternative.points)}" fill="none" stroke="#8372b3" stroke-width="2.5"/>`:''}
 <line x1="${x(now)}" y1="${top}" x2="${x(now)}" y2="${H-bottom}" stroke="#b2c7bc" stroke-dasharray="3 4"/><circle cx="${x(now)}" cy="${y(s.sbp)}" r="4.5" fill="#19877d" stroke="white" stroke-width="2"/><text x="${x(now)+8}" y="17" fill="#749487" font-size="11">NOW · ${now} MIN</text><text x="4" y="13" fill="#819990" font-size="10">mmHg</text></svg>`;
}
function header(title,subtitle,actions=''){return `<div class="pagehead"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function replay(){return `<div class="replay"><button id="play" aria-label="${playing?'Pause':'Play'} synthetic replay">${icon(playing?'pause':'play')}${playing?'Pause':'Replay'}</button><label for="timeline">Session time</label><input id="timeline" type="range" min="15" max="210" step="1" value="${now}" aria-label="Replay minute"><strong>${Math.floor(now/60)}h ${String(now%60).padStart(2,'0')}m / 4h</strong><select id="speed" aria-label="Replay speed"><option value="2" ${speed===2?'selected':''}>2 min / sec</option><option value="5" ${speed===5?'selected':''}>5 min / sec</option></select><button id="quality" aria-pressed="${quality}" title="Simulate unreliable recent sensor observations">${icon('settings')}${quality?'Restore sensors':'Test dropout'}</button></div>`;}
function profile(p,s){return `<div class="profile-header"><div class="profile"><div class="profile-avatar">${esc(p.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div><div><h2>${esc(p.name)}</h2><div class="meta">${esc(p.id)} · ${esc(p.age)} years · ${esc(p.sex)} · ${p.weight.toFixed(0)} kg dry weight</div></div></div><span class="tag">SESSION ${String(Math.floor(now/60)).padStart(2,'0')}:${String(now%60).padStart(2,'0')}</span></div>
 <div class="vitals">${[['Systolic pressure',s.valid?s.bp.sbp.toFixed(0):'—','mmHg',s.valid?`Cuff ${s.cuffAge} min ago`:'Awaiting valid cuff'],['Heart rate',s.valid?s.last.hr:'—','bpm','Synthetic pulse sensor'],['Relative blood volume',s.valid?s.last.rbv.toFixed(1):'—','%','Relative to session start'],['Fluid removed',s.valid?s.last.removed.toFixed(2):'—','L',`${(s.last?.uf??p.uf).toFixed(2)} L/h UF stream`]].map(([l,n,u,d])=>`<div class="vital"><div class="vital-label">${l}</div><div class="vital-num">${n}<span class="vital-unit">${u}</span></div><div class="vital-sub">${d}</div></div>`).join('')}</div>`;}
function unit(){
 const p=current(),{s,f}=stateOf(),all=patients.map(p=>({p,...stateOf(p)})),urgent=all.filter(x=>['review','current-low'].includes(x.f.status)).length,watch=all.filter(x=>x.f.status==='watch').length;
 const stats=[['users',patients.length,'Synthetic patients',''],['alert',urgent,'Priority reviews','warn'],['pulse',watch,'On watch',''],['clock','30 <small>min</small>','Forecast horizon','']];
 return header('Dialysis command centre','A clearer view of every patient. One step ahead of pressure drops.',`<button id="export">${icon('download')} Export review</button><button class="primary" data-view="scenarios">${icon('flask')} Scenario lab</button>`)+
 `<div class="stats">${stats.map(([i,v,l,c])=>`<div class="stat ${c}"><div class="stat-icon">${icon(i)}</div><div><div class="stat-value">${v}</div><div class="stat-label">${l}</div></div></div>`).join('')}</div>
 <div class="workbench"><section class="panel patient-panel" aria-label="Patient selection"><div class="panel-head"><h3>Active sessions</h3><span class="tag">${patients.length}</span></div><div class="search">${icon('search')}<input id="search" placeholder="Find a patient" aria-label="Find a patient" value="${esc(query)}"></div><div class="patient-list">${all.filter(x=>(x.p.name+x.p.id).toLowerCase().includes(query.toLowerCase())).map(({p:pt,s:st,f:fc})=>`<button class="patient ${pt.id===selected?'selected':''}" data-patient="${pt.id}" aria-pressed="${pt.id===selected}"><span class="patient-top"><span class="patient-name">${esc(pt.name)}</span><span class="bed">BED ${esc(pt.bed)}</span></span><span class="patient-meta">${esc(pt.id)} · ${pt.age}y · ${esc(pt.sex)}</span><span class="patient-bottom">${pill(fc)}<span>${st.valid?st.bp.sbp.toFixed(0):'—'} <span class="bed">mmHg</span></span></span></button>`).join('')||'<div class="empty">No matching patients.</div>'}</div><div class="patient-note">All identities and observations are synthetic. Replay time is shared across sessions.</div></section>
 <div class="detail"><section class="panel">${profile(p,s)}</section><section class="panel"><div class="forecast-head"><h3>Pressure trajectory</h3><div class="legend"><span><i class="swatch"></i>Observed</span><span><i class="swatch dashed"></i>Forecast</span><span><i class="swatch band"></i>Sensitivity band</span></div></div><div class="chart-wrap">${chart(p,s,f)}</div><div class="forecast-foot">Patient-specific, 30-minute projection · Shading shows model sensitivity, not a calibrated confidence interval.</div>
 <div class="alert-strip ${f.status==='stable'?'stable':''}"><div class="alert-main">${icon(f.status==='stable'?'check':'alert')}<div><div class="alert-title">${!f.valid?'Reliable observations needed':f.status==='current-low'?'Latest estimate is below the reference threshold':f.crossing!==null?`Projected to cross 90 mmHg in ${Math.max(0,f.crossing-now)} minutes`:f.status==='watch'?'Sensitivity band reaches the reference threshold':'No projected threshold crossing in this window'}</div><div class="alert-desc">${!f.valid?'Restore sensor quality to resume forecasting.':'Review observations and symptoms. All treatment decisions remain with the clinical team.'}</div></div></div><button id="review" ${!f.valid?'disabled':''}>${icon('check')} Mark reviewed</button></div></section>
 <div class="two-col"><section class="panel"><div class="panel-head"><h3>What shapes this forecast</h3>${icon('chart')}</div><div class="body"><div class="drivers">${s.valid?s.drivers.map(d=>`<div class="driver"><span>${d.label}</span><b>${d.value}</b></div>`).join(''):'Awaiting valid observations.'}</div><div class="model-note">History sets the physiological prior. Sensor data updates the twin; prior episode count is context only.</div></div></section>
 <section class="panel"><div class="panel-head"><h3>One patient. Two data streams.</h3>${icon('database')}</div><div class="body"><div class="fusion"><div class="fusion-source">${icon('file')}<br>Historical record<small>Weight · refill · baseline BP</small></div><span class="fusion-plus">+</span><div class="fusion-source">${icon('pulse')}<br>Sensor stream<small>Pressure · pulse · blood volume</small></div></div><div class="fusion-result"><span>Continuously updated twin</span><b>${s.valid?s.completeness+'% quality':'Withheld'}</b></div><div class="model-note">Cuff readings every 5 minutes; other synthetic sensors every minute.</div></div></section></div></div></div>${replay()}`;
}
function scenarios(){const p=current(),{s,f}=stateOf(),alt=forecast(p,s,{uf:scenarioUF});return header('Scenario lab','Explore a hypothetical fluid-removal change for the selected synthetic patient.',`<button data-view="unit">${icon('grid')} Back to sessions</button>`)+`<div class="notice">Simulation only. A gentler removal rate can leave more fluid unremoved. These curves do not prescribe treatment or control a dialysis machine.</div><div class="scenario-layout"><section class="panel"><div class="panel-head"><h3>Scenario inputs</h3>${icon('flask')}</div><div class="body scenario-controls"><div class="field"><label for="scenario-patient">Synthetic patient</label><select id="scenario-patient">${patients.map(pt=>`<option value="${pt.id}" ${pt.id===selected?'selected':''}>${esc(pt.name)} · ${pt.id}</option>`).join('')}</select></div><div class="field"><label for="uf">Hypothetical UF rate</label><div class="field-value">${scenarioUF.toFixed(2)} <span class="meta">L/hour</span></div><input id="uf" type="range" min="0" max="1.5" step="0.02" value="${scenarioUF}"><div class="compare-note">Observed rate: ${(s.last?.uf??p.uf).toFixed(2)} L/hour</div></div><div class="field"><label>Comparison window</label><div class="field-value">30 <span class="meta">minutes</span></div><div class="compare-note">Both simulations start at minute ${now} with the same estimated patient state.</div></div><button id="reset-scenario">Match observed rate</button><div class="model-note">No saline, medication, or machine commands are issued. No scenario becomes the patient record.</div></div></section><div class="detail"><section class="panel"><div class="forecast-head"><h3>Predicted pressure comparison</h3><div class="legend"><span><i class="swatch dashed"></i>Observed rate</span><span><i class="swatch" style="background:#8372b3"></i>Scenario</span></div></div><div class="chart-wrap">${chart(p,s,f,alt)}</div><div class="comparison"><div><div class="eyebrow">Observed rate projection</div><div class="compare-num">${f.valid?f.nadir.toFixed(1):'—'} <span class="meta">mmHg</span></div><div class="compare-note">Predicted lowest SBP<br>${f.valid?f.removed.toFixed(2):'—'} L removed over next 30 minutes</div></div><div><div class="eyebrow">Hypothetical projection</div><div class="compare-num" style="color:#8372b3">${alt.valid?alt.nadir.toFixed(1):'—'} <span class="meta">mmHg</span></div><div class="compare-note">Predicted lowest SBP<br>${alt.valid?alt.removed.toFixed(2):'—'} L removed over next 30 minutes</div></div></div></section><section class="panel"><div class="body prose"><h3 style="margin-top:0">The tradeoff stays visible</h3><p>${alt.valid?`This scenario removes <strong>${Math.abs(f.removed-alt.removed).toFixed(2)} L ${alt.removed<f.removed?'less':'more'}</strong> fluid over 30 minutes. The model estimates a <strong>${(alt.nadir-f.nadir).toFixed(1)} mmHg</strong> change in the pressure nadir.`:'No comparison is available until observations are reliable.'}</p><p>Pressure is only one part of dialysis care. Volume status, adequacy, symptoms and clinician judgement are outside this simplified simulation.</p></div></section></div></div>${replay()}`;}
function evidence(){const e=evaluation,fmt=(v,d=1)=>Number.isFinite(v)?v.toFixed(d):'—';return header('Evidence & model','Inspect the assumptions, the evaluation and the limits of the prototype.',`<button id="sample">${icon('download')} Sample data</button><button id="import">${icon('database')} Import synthetic JSON</button><input id="import-file" type="file" accept="application/json,.json">`)+`<div class="notice">This is an engineering proof of concept. Evaluation uses generated patients, not clinical records. Synthetic performance does not establish clinical safety, calibration or patient benefit.</div><div class="evidence-grid"><section class="panel"><div class="panel-head"><h3>Separate synthetic benchmark</h3><span class="tag">REPRODUCIBLE</span></div><div class="metrics-summary"><div><b>${e?.patients??'—'}</b><span>independent synthetic patients</span></div><div><b>${e?.windows??'—'}</b><span>30-minute forecast windows</span></div></div><table class="table"><thead><tr><th>Method</th><th>Nadir MAE ↓</th><th>Event recall ↑</th></tr></thead><tbody>${e?Object.entries(e.methods).map(([name,m])=>`<tr><td>${esc(name)}</td><td><strong>${fmt(m.mae)} mmHg</strong></td><td>${fmt(m.recall*100)}%</td></tr>`).join(''):'<tr><td colspan="3">Evaluation file unavailable. Run npm run evaluate.</td></tr>'}</tbody></table><div class="footnote">Event: at least one future simulated SBP &lt;90 mmHg within 30 minutes. Windows already below 90 are excluded. Same-generating-family evaluation; no independent clinical validation. <a href="./data/evaluation.json" download>Download full metrics, seed and confusion matrices</a></div></section><section class="panel"><div class="panel-head"><h3>Inside the twin</h3>${icon('shield')}</div><div class="body prose"><p><strong>Mechanistic model + online state estimation.</strong> Fluid removal competes with plasma refilling. An estimated circulating-volume deficit links that balance to pressure.</p><p>A scalar Kalman filter updates the deficit using relative blood volume. Recent cuff trends correct the projection. This is a transparent adaptive algorithm, with no pretrained language model or claimed clinical training.</p><p class="api-label">${MODEL_VERSION}</p><details><summary>Equations and uncertainty</summary><p>dD/dt = (UF - refill) / 60<br>SBP change ≈ -sensitivity × change in D<br>Forecast = current BP + 0.7 × physiology change + 0.3 × trend change.</p><p>The shaded sensitivity band is heuristic. The 21-member crossing fraction is not a calibrated event probability.</p></details></div></section><section class="panel"><div class="panel-head"><h3>Clinical basis & prior art</h3>${icon('file')}</div><div class="body prose"><p>KDIGO identifies symptomatic pressure falls or systolic pressure below 90 mmHg as reasons for reassessment. NEPHRA uses the absolute threshold as a narrow demo endpoint; symptoms and other definitions remain outside scope.</p><p><a href="https://kdigo.org/wp-content/uploads/2017/05/KDIGO-BP-Volume-in-Dialysis-FINAL.pdf" target="_blank" rel="noreferrer">KDIGO: blood pressure and volume management</a></p><p>Early IDH prediction already exists in published research. Our proposed contribution is an inspectable twin, visible tradeoffs and review-note preparation.</p><p><a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10310501/" target="_blank" rel="noreferrer">Real-time IDH prediction study</a></p></div></section><section class="panel"><div class="panel-head"><h3>Submission resources</h3>${icon('download')}</div><div class="body prose"><p>All demo patient data is generated locally. Import accepts only the documented synthetic JSON schema and never uploads a file.</p><div class="docs-links"><a href="./docs/architecture.pdf" target="_blank">Architecture PDF</a><a href="./docs/presentation.pdf" target="_blank">Project presentation</a><a href="./docs/model-card.md" download>Model card</a></div><h3>Before a clinical pilot</h3><p>Partner with a nephrology unit, obtain ethics and data approvals, validate retrospectively with patient-level separation, then evaluate silently before any assisted clinical workflow.</p></div></section></div>`;}
function workflow(){const p=current(),{s,f}=stateOf(),w=workload(assumptions);return header('Review & handover','Prepare routine documentation, then keep a human in the decision loop.',`<button id="export">${icon('download')} Export review draft</button>`)+`<div class="evidence-grid"><section class="panel"><div class="panel-head"><h3>Automatically assembled review draft</h3><span class="tag">${esc(p.id)}</span></div><div class="body"><pre class="note-preview">${esc(handover(p,s,f,events))}</pre><div class="actions" style="margin-top:16px"><button class="primary" id="review" ${!f.valid?'disabled':''}>${icon('check')} Mark reviewed</button><button id="export-audit">Export review log</button></div><p class="model-note">A local review marker is a demo workflow action, not an authenticated clinical signature. This browser stores up to 100 review actions.</p></div></section><section class="panel"><div class="panel-head"><h3>Workload target calculator</h3>${icon('clock')}</div><div class="body"><div class="notice">Planning assumptions, not measured time savings. This calculator covers repetitive preparation only.</div><div class="workload-fields">${[['patients','Patients per day'],['checks','Review cycles per patient'],['manual','Manual preparation (sec)'],['review','Assisted preparation (sec)']].map(([k,l])=>`<div class="field"><label for="work-${k}">${l}</label><input type="number" id="work-${k}" data-assumption="${k}" min="${k==='manual'?1:0}" max="10000" value="${assumptions[k]}"></div>`).join('')}</div><div class="workload-result"><strong>${w.reduction.toFixed(0)}%</strong><span>modelled reduction in preparation time</span></div><div class="drivers"><div class="driver"><span>Manual preparation</span><b>${w.before.toFixed(1)} min/day</b></div><div class="driver"><span>Assisted preparation</span><b>${w.after.toFixed(1)} min/day</b></div><div class="driver"><span>Potential time difference</span><b>${w.saved.toFixed(1)} min/day</b></div></div><div class="model-note">A 90% target assumes 90 seconds becomes 9 seconds. Clinical assessment, bedside care, checks, training and exception handling are excluded. Validate using a prospective time-and-motion study.</div></div></section><section class="panel"><div class="panel-head"><h3>Local review history</h3><button id="clear-log">Clear demo log</button></div><div class="body">${events.length?events.slice(-8).reverse().map(x=>`<div class="audit-row"><strong>${esc(x.patient)}</strong> · ${esc(x.action)} at minute ${x.minute}<br><small>${esc(x.time)}</small></div>`).join(''):'<div class="empty">No reviews recorded in this browser.</div>'}</div></section><section class="panel"><div class="panel-head"><h3>Pilot measurement plan</h3>${icon('chart')}</div><div class="body prose"><p>Time the same chart preparation task with and without NEPHRA using randomised task order and equivalent case complexity.</p><p>Report median time, omissions, corrections, extra reviews and clinician satisfaction. Count setup time and false alerts separately. Do not infer a 90% reduction in total nursing work.</p></div></section></div>`;}
function render(){document.getElementById('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="./favicon.svg" alt="">NEPHRA</div><div class="brand-sub">THE DIALYSIS DIGITAL TWIN</div><div class="nav-label">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${[['unit','grid','Live sessions'],['scenarios','flask','Scenario lab'],['workflow','file','Review & handover'],['evidence','chart','Evidence & model']].map(([v,i,l])=>`<button data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}</nav><div class="sidebar-foot">${icon('shield')}<br><strong>Built for a thoughtful review.</strong><br>Synthetic research prototype<br>Version 1.0 · October 2026<hr><a href="./docs/presentation.pdf" target="_blank">Explore the project</a></div></aside><div class="main-wrap"><header class="topbar"><div class="crumb">Clinical workspace &nbsp; / &nbsp; <b>Dialysis unit</b></div><div class="topright"><span class="tag orange">SYNTHETIC DEMO</span><span class="avatar" title="Demo reviewer; no authenticated account">DR</span></div></header><main id="main" class="content">${view==='unit'?unit():view==='scenarios'?scenarios():view==='evidence'?evidence():workflow()}<footer class="bottomline"><span>Research prototype · No real patient data · No treatment automation</span><span>Local computation &nbsp; · &nbsp; <a href="./docs/model-card.md" download>Model card</a></span></footer></main></div></div>`;bind();}
function stop(){playing=false;clearInterval(timer);timer=null;}
function bind(){
 document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{stop();view=b.dataset.view;render();});
 document.querySelectorAll('[data-patient]').forEach(b=>b.onclick=()=>{selected=b.dataset.patient;scenarioUF=Math.max(0,current().uf-.2);render();});
 const on=(id,event,fn)=>{const el=document.getElementById(id);if(el)el.addEventListener(event,fn);};
 on('timeline','input',e=>{const v=+e.target.value;stop();now=v;render();document.getElementById('timeline').focus();});
 on('play','click',()=>{if(playing)stop();else{playing=true;timer=setInterval(()=>{now=Math.min(210,now+speed);if(now===210)stop();render();},1000);}render();});
 on('speed','change',e=>speed=+e.target.value);
 on('quality','click',()=>{quality=!quality;render();toast(quality?'Recent readings marked unreliable; forecasts are withheld.':'Good sensor quality restored.');});
 on('search','input',e=>{query=e.target.value;const pos=e.target.selectionStart;render();const input=document.getElementById('search');input.focus();input.setSelectionRange(pos,pos);});
 on('scenario-patient','change',e=>{selected=e.target.value;render();});
 on('uf','input',e=>{scenarioUF=+e.target.value;render();document.getElementById('uf').focus();});
 on('reset-scenario','click',()=>{scenarioUF=stateOf().s.last?.uf??current().uf;render();});
 on('review','click',()=>{const {s,f}=stateOf();if(!s.valid||!f.valid)return;saveEvent(`Observed-rate forecast reviewed (${f.status})`);render();toast('Review recorded in this browser. No treatment action sent.');});
 on('export','click',()=>{const {s,f}=stateOf();download(`NEPHRA-${selected}-review.txt`,handover(current(),s,f,events));toast('Review draft exported.');});
 on('export-audit','click',()=>download('NEPHRA-local-review-log.json',JSON.stringify({demo:true,events},null,2),'application/json'));
 on('clear-log','click',()=>{events=[];try{localStorage.removeItem('nephra-reviews-v1');}catch{}render();toast('Local demo log cleared.');});
 document.querySelectorAll('[data-assumption]').forEach(el=>el.onchange=()=>{const value=+el.value;if(!Number.isFinite(value)||value<Number(el.min)||value>10000){toast('Enter a value within the displayed bounds.');render();return;}assumptions[el.dataset.assumption]=value;render();});
 on('sample','click',()=>download('nephra-synthetic-session.json',JSON.stringify({synthetic:true,patient:initialPatients[0],readings:streams[initialPatients[0].id]},null,2),'application/json'));
 on('import','click',()=>document.getElementById('import-file').click());
 on('import-file','change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2e6)throw Error('File exceeds 2 MB.');const d=JSON.parse(await file.text());if(d.synthetic!==true)throw Error('Only explicitly synthetic demo sessions are accepted.');validatePatient(d.patient);validateReadings(d.readings);if(d.readings.at(-1).minute<30)throw Error('Supply at least 30 minutes.');const p={...d.patient,name:String(d.patient.name||d.patient.id).slice(0,60),age:Number.isFinite(d.patient.age)?d.patient.age:'Unknown',sex:String(d.patient.sex||'Unknown').slice(0,10),bed:'IMP'};patients=patients.filter(x=>x.id!==p.id).concat(p);streams[p.id]=d.readings;selected=p.id;now=Math.min(120,d.readings.at(-1).minute);view='unit';stop();render();toast('Synthetic session imported locally.');}catch(err){toast('Import rejected: '+err.message);}});
}
render();
fetch('./data/evaluation.json').then(r=>r.ok?r.json():null).then(d=>{evaluation=d;if(view==='evidence')render();}).catch(()=>{});

